from json import dumps


class Tree:
    def __init__(self, label, children=None):
        self.label = label
        self.children = children if children is not None else []

    def __dict__(self):
        return {self.label: [c.__dict__() for c in sorted(self.children)]}

    def __str__(self, indent=None):
        return dumps(self.__dict__(), indent=indent)

    def __lt__(self, other):
        return self.label < other.label

    def __eq__(self, other):
        return self.__dict__() == other.__dict__()

    def from_pov(self, from_node):
        # Build an undirected view of the tree (each node's neighbours are its
        # parent plus its children) and locate the node we want to re-root at.
        adj = {}
        target = None

        def build(node, parent):
            nonlocal target
            neighbors = []
            if parent is not None:
                neighbors.append(parent)
            for child in node.children:
                neighbors.append(child)
                build(child, node)
            adj[node] = neighbors
            if node.label == from_node:
                target = node

        build(self, None)

        if target is None:
            raise ValueError("Tree could not be reoriented")

        # Rebuild the tree from the new root, dragging relationships along:
        # each node keeps every neighbour except the one we came from.
        def rebuild(node, parent):
            children = [rebuild(n, node) for n in adj[node] if n is not parent]
            return Tree(node.label, children)

        return rebuild(target, None)

    def path_to(self, from_node, to_node):
        # Re-orient the tree at the source node, then walk down to the target.
        tree = self.from_pov(from_node)

        def search(node):
            if node.label == to_node:
                return [node.label]
            for child in node.children:
                sub = search(child)
                if sub is not None:
                    return [node.label] + sub
            return None

        path = search(tree)
        if path is None:
            raise ValueError("No path found")
        return path

from json import dumps


class Tree:
    def __init__(self, label, children=None):
        self.label = label
        self.children = children if children is not None else []

    def __dict__(self):
        return {self.label: [c.__dict__() for c in sorted(self.children)]}

    def __str__(self, indent=None):
        return dumps(self.__dict__(), indent=indent)

    def __lt__(self, other):
        return self.label < other.label

    def __eq__(self, other):
        return self.__dict__() == other.__dict__()

    def from_pov(self, from_node):
        # Locate the chain of nodes from the root down to from_node.
        def find_path(node):
            if node.label == from_node:
                return [node]
            for child in node.children:
                sub = find_path(child)
                if sub is not None:
                    return [node] + sub
            return None

        path = find_path(self)
        if path is None:
            raise ValueError("Tree could not be reoriented")

        # Rebuild top-down: each node keeps its off-path children and gains the
        # previously built node as a child (the former parent becomes a child).
        rebuilt = None
        for i, node in enumerate(path):
            path_child = path[i + 1] if i + 1 < len(path) else None
            children = [c for c in node.children if c is not path_child]
            if rebuilt is not None:
                children.append(rebuilt)
            rebuilt = Tree(node.label, children)
        return rebuilt

    def path_to(self, from_node, to_node):
        # Re-orient the tree at the source node, then walk down to the target.
        tree = self.from_pov(from_node)

        def search(node):
            if node.label == to_node:
                return [node.label]
            for child in node.children:
                sub = search(child)
                if sub is not None:
                    return [node.label] + sub
            return None

        path = search(tree)
        if path is None:
            raise ValueError("No path found")
        return path
